contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        bool isCall,
        bool isLong,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        uint256 fakeFee
    ) public payable {
        require(fakeFee >= 30, "need invalid fee");

        address[] memory emptyAddrs = new address[](0);
        C.ERC20Asset[] memory noErc20 = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory noErc721 = new C.ERC721Asset[](0);

        C.Order memory order = C.Order({
            maker: address(this),
            isCall: isCall,
            isLong: isLong,
            baseAsset: address(c),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: emptyAddrs,
            floorTokens: emptyAddrs,
            erc20Assets: noErc20,
            erc721Assets: noErc721
        });

        // Rule 1: maker cancel succeeds and marks the order cancelled.
        bytes32 h1 = c.hashOrder(order);
        require(!c.cancelledOrders(h1), "precondition: not yet cancelled");
        c.cancel(order);
        bool cancelledAfter = c.cancelledOrders(h1);

        // Rule 2: a non-maker (any other account's order) cancel always reverts.
        order.maker = address(0xBEEF);
        bytes32 h2 = c.hashOrder(order);
        require(!c.cancelledOrders(h2), "precondition: not yet cancelled 2");
        bool revertedOther;
        try c.cancel(order) { revertedOther = false; } catch { revertedOther = true; }
        bool cancelledOther = c.cancelledOrders(h2);

        // Rule 3: setFee with fee >= 30 always reverts.
        bool revertedFee;
        try c.setFee(fakeFee) { revertedFee = false; } catch { revertedFee = true; }

        assert(
            cancelledAfter &&
            revertedOther &&
            !cancelledOther &&
            revertedFee
        );
    }

    receive() external payable {}
}

